public class JwtAuthenticationFilter extends OncePerRequestFilter {
    private final JwtTokenProvider tokenProvider;
    private final UserDetailsService userDetailsService;

    @Override
    protected void doFilterInternal(HttpServletRequest request,
                                    HttpServletResponse response,
                                    FilterChain filterChain) throws ServletException, IOException {
        var token = extractTokenFromHeader(request);
        if (token != null && tokenProvider.validateToken(token)) {
            var username = tokenProvider.getUsernameFromToken(token);
            var userDetails = userDetailsService.loadUserByUsername(username); // Loads user + authorities
            var authentication = new UsernamePasswordAuthenticationToken(
                userDetails, null, userDetails.getAuthorities()); // Create authenticated token
            SecurityContextHolder.getContext().setAuthentication(authentication); // Store in context
        }
        filterChain.doFilter(request, response); // Continue to next filter or controller
    }

    private String extractTokenFromHeader(HttpServletRequest request) {
        var bearerToken = request.getHeader("Authorization");
        return (bearerToken != null && bearerToken.startsWith("Bearer "))
            ? bearerToken.substring(7) : null;
    }
}

@Service
public class CustomUserDetailsService implements UserDetailsService {
    private final UserRepository userRepository;

    @Override
    public UserDetails loadUserByUsername(String username) throws UsernameNotFoundException {
        var user = userRepository.findByUsername(username)
            .orElseThrow(() -> new UsernameNotFoundException("User not found"));
        var authorities = user.getRoles().stream() // Fetch roles from database
            .map(role -> new SimpleGrantedAuthority("ROLE_" + role.getName())) // Add ROLE_ prefix
            .collect(Collectors.toList());
        return new User(user.getUsername(), user.getPassword(), authorities); // Return UserDetails with roles
    }
}

@RestController
@RequestMapping("/api/users")
public class UserController {
    @PreAuthorize("hasRole('ADMIN')") // Requires ROLE_ADMIN authority
    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deleteUser(@PathVariable Long id) {
        userService.delete(id);
        return ResponseEntity.noContent().build();
    }

    @PreAuthorize("hasAnyRole('ADMIN', 'MODERATOR')") // Either role allowed
    @GetMapping
    public List<UserDto> listUsers() {
        return userService.findAll();
    }
}
